import hashlib

# Pinned fingerprints for known hosts
PINNED_FINGERPRINTS = {
    "feed.certpin.dev": "a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2",
}


